import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadFont = makeLoadFont('Orbitron');

// Load high-tech monospace font at module level.
// delayRender/continueRender are handled internally by loadFont()
const { fontFamily } = loadFont();



export type WorkflowDiagramProps = Record<string, any>;

const WorkflowDiagram: React.FC<WorkflowDiagramProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 8,
  glowColor = "#00FFFF",
  strokeWidth = 3,
  circleRadiusRatio = 0.12,
  agentLabel = "[ AGENT ]",
  toolsLabel = "[ TOOLS ]",
  approvalsLabel = "[ APPROVALS ]",
  stateLabel = "[ STATE ]",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Parse safety for background transparency
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Total frames in the animation
  const totalFrames = durationInSeconds * fps;

  // Node horizontal placement (perfectly symmetrical)
  const nodeXPositions = [
    width * 0.20,
    width * 0.40,
    width * 0.60,
    width * 0.80
  ];

  // Circle and layout constants
  const radius = Math.min(width, height) * circleRadiusRatio;
  const centerY = height * 0.46;
  const textY = height * 0.64;

  const iconStyle: React.CSSProperties = {
    width: "50%",
    height: "50%",
    filter: `drop-shadow(0 0 6px ${glowColor}80)`,
    transition: "none",
  };

  // 1. Connection lines rendering
  const lines = [0, 1, 2].map((i) => {
    const xStart = nodeXPositions[i] + radius;
    const xEnd = nodeXPositions[i + 1] - radius;

    // Sequential timing based on index
    const startPct = 0.13 + i * 0.16;
    const endPct = startPct + 0.08;
    const startFrame = startPct * totalFrames;
    const endFrame = endPct * totalFrames;

    // Line drawing progress
    const lineProgress = interpolate(
      frame,
      [startFrame, endFrame],
      [0, 1],
      { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
    );

    const currentWidth = (xEnd - xStart) * lineProgress;

    // Fade-in progress for the boundary dots
    const dot1Progress = interpolate(
      frame,
      [startFrame, startFrame + 5],
      [0, 1],
      { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
    );

    const dot2Progress = interpolate(
      frame,
      [endFrame - 4, endFrame + 1],
      [0, 1],
      { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
    );

    return (
      <React.Fragment key={`line-${i}`}>
        {/* Glow horizontal connector line */}
        <div
          style={{
            position: "absolute",
            left: xStart,
            top: centerY,
            width: currentWidth,
            height: Math.max(1, Math.min(width, height) * 0.003),
            backgroundColor: glowColor,
            transform: "translateY(-50%)",
            boxShadow: `0 0 8px ${glowColor}a0`,
            zIndex: 1,
            transition: "none",
          }}
        />

        {/* Start connector point dot */}
        {dot1Progress > 0 && (
          <div
            style={{
              position: "absolute",
              left: xStart,
              top: centerY,
              width: Math.max(4, Math.min(width, height) * 0.008),
              height: Math.max(4, Math.min(width, height) * 0.008),
              borderRadius: "50%",
              backgroundColor: glowColor,
              transform: `translate(-50%, -50%) scale(${dot1Progress})`,
              boxShadow: `0 0 10px ${glowColor}`,
              opacity: dot1Progress,
              zIndex: 2,
              transition: "none",
            }}
          />
        )}

        {/* End connector point dot */}
        {dot2Progress > 0 && (
          <div
            style={{
              position: "absolute",
              left: xEnd,
              top: centerY,
              width: Math.max(4, Math.min(width, height) * 0.008),
              height: Math.max(4, Math.min(width, height) * 0.008),
              borderRadius: "50%",
              backgroundColor: glowColor,
              transform: `translate(-50%, -50%) scale(${dot2Progress})`,
              boxShadow: `0 0 10px ${glowColor}`,
              opacity: dot2Progress,
              zIndex: 2,
              transition: "none",
            }}
          />
        )}
      </React.Fragment>
    );
  });

  // 2. Nodes rendering (Circles + Icons + Glow + Labels)
  const renderedNodes = [0, 1, 2, 3].map((i) => {
    const x = nodeXPositions[i];

    // Node build-up timing
    const nodeStartPct = 0.05 + i * 0.16;
    const nodeEndPct = nodeStartPct + 0.08;
    const nodeStartFrame = nodeStartPct * totalFrames;
    const nodeEndFrame = nodeEndPct * totalFrames;

    const nodeProgress = interpolate(
      frame,
      [nodeStartFrame, nodeEndFrame],
      [0, 1],
      { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
    );

    // Elastic pop-in effect
    const nodeScale = interpolate(
      nodeProgress,
      [0, 0.7, 1],
      [0, 1.05, 1],
      { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
    );

    const nodeOpacity = interpolate(
      nodeProgress,
      [0, 1],
      [0, 1],
      { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
    );

    // Subtle idle breathing glow after fully revealed
    const breathingStartFrame = nodeEndFrame;
    const isFullyRevealed = frame >= breathingStartFrame;
    const breathingWave = Math.sin((frame - breathingStartFrame) * (2 * Math.PI / 90));

    const pulseScale = isFullyRevealed ? interpolate(breathingWave, [-1, 1], [0.98, 1.02]) : 1.0;
    const pulseGlow = isFullyRevealed ? interpolate(breathingWave, [-1, 1], [0.75, 1.25]) : 1.0;

    const finalScale = nodeScale * pulseScale;
    const glowShadow = `0 0 ${15 * pulseGlow}px ${glowColor}60, inset 0 0 ${8 * pulseGlow}px ${glowColor}20`;

    // Dynamic label selector
    let labelText = "";
    if (i === 0) labelText = agentLabel;
    else if (i === 1) labelText = toolsLabel;
    else if (i === 2) labelText = approvalsLabel;
    else labelText = stateLabel;

    // Customized crisp 2D high-tech icons
    let iconSVG;
    if (i === 0) {
      // Robot Head (Agent)
      iconSVG = (
        <svg viewBox="0 0 100 100" style={iconStyle}>
          <line x1="50" y1="24" x2="50" y2="12" stroke={glowColor} strokeWidth={strokeWidth} strokeLinecap="round" />
          <circle cx="50" cy="12" r={strokeWidth * 1.2} fill={glowColor} />
          <rect x="17" y="40" width="6" height="20" rx="3" fill={glowColor} />
          <rect x="77" y="40" width="6" height="20" rx="3" fill={glowColor} />
          <rect x="23" y="28" width="54" height="44" rx="12" stroke={glowColor} strokeWidth={strokeWidth} fill="none" />
          <circle cx="40" cy="46" r="4" fill={glowColor} />
          <circle cx="60" cy="46" r="4" fill={glowColor} />
          <path d="M 40 58 Q 50 64 60 58" stroke={glowColor} strokeWidth={strokeWidth} strokeLinecap="round" fill="none" />
        </svg>
      );
    } else if (i === 1) {
      // Crossed Tools (Tools)
      iconSVG = (
        <svg viewBox="0 0 100 100" style={iconStyle}>
          <path d="M 22 22 L 40 40" stroke={glowColor} strokeWidth={strokeWidth * 2.2} strokeLinecap="round" />
          <line x1="40" y1="40" x2="68" y2="68" stroke={glowColor} strokeWidth={strokeWidth} strokeLinecap="round" />
          <line x1="68" y1="68" x2="74" y2="74" stroke={glowColor} strokeWidth={strokeWidth * 1.5} strokeLinecap="square" />
          <line x1="34" y1="66" x2="66" y2="34" stroke={glowColor} strokeWidth={strokeWidth * 1.2} strokeLinecap="round" />
          <path
            d="M 21 57 A 11 11 0 1 0 43 79 L 37 73 A 4 4 0 0 1 31 67 Z"
            fill="none"
            stroke={glowColor}
            strokeWidth={strokeWidth}
            strokeLinecap="round"
          />
          <circle cx="72" cy="28" r="8" stroke={glowColor} strokeWidth={strokeWidth} fill="none" />
          <circle cx="72" cy="28" r="3.5" fill={glowColor} />
        </svg>
      );
    } else if (i === 2) {
      // Shield with Checkmark (Approvals)
      iconSVG = (
        <svg viewBox="0 0 100 100" style={iconStyle}>
          <path
            d="M 50 18 C 66 18, 77 22, 78 26 C 78 54, 65 72, 50 82 C 35 72, 22 54, 22 26 C 23 22, 34 18, 50 18 Z"
            stroke={glowColor}
            strokeWidth={strokeWidth}
            strokeLinecap="round"
            strokeLinejoin="round"
            fill="none"
          />
          <path
            d="M 38 48 L 46 56 L 62 38"
            stroke={glowColor}
            strokeWidth={strokeWidth * 1.2}
            strokeLinecap="round"
            strokeLinejoin="round"
            fill="none"
          />
        </svg>
      );
    } else {
      // Stacked cylinders (State)
      iconSVG = (
        <svg viewBox="0 0 100 100" style={iconStyle}>
          <line x1="30" y1="26" x2="30" y2="71" stroke={glowColor} strokeWidth={strokeWidth} />
          <line x1="70" y1="26" x2="70" y2="71" stroke={glowColor} strokeWidth={strokeWidth} />
          <ellipse cx="50" cy="26" rx="20" ry="7" stroke={glowColor} strokeWidth={strokeWidth} fill="none" />
          <ellipse cx="50" cy="41" rx="20" ry="7" stroke={glowColor} strokeWidth={strokeWidth} fill="none" />
          <ellipse cx="50" cy="56" rx="20" ry="7" stroke={glowColor} strokeWidth={strokeWidth} fill="none" />
          <ellipse cx="50" cy="71" rx="20" ry="7" stroke={glowColor} strokeWidth={strokeWidth} fill="none" />
        </svg>
      );
    }

    return (
      <React.Fragment key={`node-${i}`}>
        {/* Glow Node Circle */}
        <div
          style={{
            position: "absolute",
            left: x,
            top: centerY,
            width: radius * 2,
            height: radius * 2,
            borderRadius: "50%",
            border: `${strokeWidth}px solid ${glowColor}`,
            boxShadow: glowShadow,
            backgroundColor: "#000000",
            transform: `translate(-50%, -50%) scale(${finalScale})`,
            opacity: nodeOpacity,
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            zIndex: 3,
            filter: `drop-shadow(0 0 8px ${glowColor}50)`,
            transition: "none",
          }}
        >
          {iconSVG}
        </div>

        {/* Text Label below Circle */}
        <div
          style={{
            position: "absolute",
            left: x,
            top: textY,
            transform: `translate(-50%, -50%) scale(${nodeScale})`,
            opacity: nodeOpacity,
            color: glowColor,
            fontFamily,
            fontSize: Math.min(width, height) * 0.024,
            fontWeight: "bold",
            letterSpacing: "4px",
            textShadow: `0 0 8px ${glowColor}c0, 0 0 20px ${glowColor}40`,
            zIndex: 4,
            textAlign: "center",
            whiteSpace: "nowrap",
            transition: "none",
          }}
        >
          {labelText}
        </div>
      </React.Fragment>
    );
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        overflow: "hidden",
        position: "relative",
      }}
    >
      {/* Network connection paths */}
      {lines}

      {/* Interactive Node modules */}
      {renderedNodes}
    </AbsoluteFill>
  );
};

export default WorkflowDiagram;